/** A name a package declares, looked up among a set's own names: any other name, an object's inherited ones among them, finds nothing. */
export const ownMark = <T>(set: Readonly<Record<string, T>>, name: string): T | undefined => (Object.hasOwn(set, name) ? set[name] : undefined);

